@block QuadCartTraj begin
    # Swing-up tables of the quadruple pendulum (design/design.py, 10 ms knots) for two controllers:
    # controller 0 plans with the full travel (+-1.5 m), controller 1 within +-0.5 m. Per controller: the
    # TVLQR gain row K and the combined feed-forward v = u* + K z* (u* the feed-forward, z* = [s, phi_1.., sd,
    # phid_1..] the nominal state), so that u = u* - K (z - z*) = v - K z: one table per gain plus one, not
    # two per state (the run time grows with the total table size),
    # looked up linearly at tau = t - t_on and held at the ends (the last row is upright at rest with the
    # balance LQR gain). interp1 is an equation-scope intrinsic, so the lookup is continuous; the firmware
    # samples these outputs at its ticks. `controller` is a run-time parameter (the dashboard's select):
    # switching needs no recompile. The table of the other controller is queried at -1 s (before its first
    # knot), which returns at once: only the chosen table is searched. Generated by design/build_models.py:
    # do not edit by hand.
    @constants begin
        NK::Int = 501
        NK2::Int = 501
    end
    @inputs tm::Real, [unit = "s"]
    @outputs begin
        ff::Real, [unit = "N", description = "Combined feed-forward v = u* + K z*"]
        Ks::Vec{10}
        sel::Real, [description = "The chosen controller (0 full travel, 1 short travel)"]
        lim::Real, [unit = "m", description = "Travel limit of the chosen controller"]
    end
    @parameters begin
        controller::Int = 0, [options = ["full travel (+-1.5 m)", "short travel (+-0.5 m)"], description = "Swing-up and balance controller: 0 full travel, 1 short travel"]
        travel::Real = 1.5, [unit = "m", description = "Travel limit of controller 0 (the end stops)"]
        travel2::Real = 0.5, [unit = "m", description = "Travel limit of controller 1"]
        t_on::Real = 1.0, [unit = "s", description = "Start of the swing-up"]
